-- init-mvp-schema.sql

create table if not exists profiles (
    id uuid primary key default gen_random_uuid(),
    email text unique,
    full_name text,
    avatar_url text,
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

create table if not exists book_categories (
    id uuid primary key default gen_random_uuid(),
    name text not null,
    slug text not null unique,
    description text,
    sort_order int default 0,
    is_active boolean default true,
    created_at timestamptz default now()
);

create table if not exists book_templates (
    id uuid primary key default gen_random_uuid(),
    category_id uuid references book_categories(id),
    name text not null,
    description text,
    cover_image_url text,
    price decimal(10,2) default 0.0,
    is_active boolean default true,
    created_at timestamptz default now()
);

create table if not exists template_pages (
    id uuid primary key default gen_random_uuid(),
    template_id uuid references book_templates(id),
    page_number int not null,
    layout_type text not null,
    default_content jsonb default '{}'::jsonb,
    created_at timestamptz default now()
);

create table if not exists user_books (
    id uuid primary key default gen_random_uuid(),
    user_id uuid references profiles(id),
    template_id uuid references book_templates(id),
    client_book_id text,
    client_template_id text,
    title text,
    status text default 'DRAFT',
    book_data text,
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

alter table user_books add column if not exists client_book_id text;
alter table user_books add column if not exists client_template_id text;
alter table user_books add column if not exists book_data text;
create unique index if not exists idx_user_books_user_client_book_id
  on user_books(user_id, client_book_id)
  where client_book_id is not null;

create table if not exists user_book_pages (
    id uuid primary key default gen_random_uuid(),
    user_book_id uuid references user_books(id) on delete cascade,
    template_page_id uuid references template_pages(id),
    page_number int not null,
    user_content jsonb default '{}'::jsonb,
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

create table if not exists user_uploads (
    id uuid primary key default gen_random_uuid(),
    user_id uuid references profiles(id),
    file_url text not null,
    file_type text,
    created_at timestamptz default now()
);

create table if not exists orders (
    id uuid primary key default gen_random_uuid(),
    user_id uuid references profiles(id),
    user_book_id uuid references user_books(id),
    total_amount decimal(10,2) not null,
    status text default 'PENDING',
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

create table if not exists order_shipping (
    id uuid primary key default gen_random_uuid(),
    order_id uuid references orders(id) on delete cascade,
    recipient_name text not null,
    phone text not null,
    address text not null,
    city text,
    tracking_number text,
    created_at timestamptz default now()
);

create table if not exists payments (
    id uuid primary key default gen_random_uuid(),
    order_id uuid references orders(id),
    amount decimal(10,2) not null,
    payment_method text not null,
    status text default 'PENDING',
    transaction_id text,
    created_at timestamptz default now()
);

