values ('fd02db72-6e16-e2a3-390a-34fb985df786', '97dafe4f-ba38-0e9e-614d-8f1abf95435b', 6, 'PAGE', $pgjson${"id":"page-5-long-distance","backgroundColor":"#E6E6FA","elements":[{"id":"p5-bg-gradient","type":"shape","shapeType":"rectangle","fill":"linear-gradient(to bottom, #E6E6FA, #DDA0DD)","x":0,"y":0,"width":800,"height":1000},{"id":"p5-main-image","type":"image","src":"https://images.unsplash.com/photo-1754769440790-fd58bfbf2540?w=600&h=400&fit=crop","x":100,"y":200,"width":600,"height":400,"objectFit":"cover","borderRadius":20},{"id":"p5-title","type":"text","content":"Miles Apart, Hearts Together","x":60,"y":80,"width":680,"height":90,"fontSize":46,"fontFamily":"Playfair Display","color":"#8B008B","fontWeight":"bold","textAlign":"center"},{"id":"p5-quote","type":"text","content":"\"Distance means so little when someone means so much.\"","x":80,"y":650,"width":640,"height":100,"fontSize":28,"fontFamily":"Dancing Script","color":"#4B0082","fontWeight":"bold","textAlign":"center"},{"id":"p5-body","type":"text","content":"Though miles separate us, you are always in my thoughts, in my heart, in every beat. I carry you with me, always.","x":80,"y":560,"width":640,"height":120,"fontSize":20,"fontFamily":"Poppins","color":"#6A5ACD","fontWeight":"normal","textAlign":"center"}]}$pgjson$)
